def taller_within(a: list[int], k: int) -> list[int]:
    if k == 0:
        return [0] * len(a)

    ranks = {value: i + 1 for i, value in enumerate(sorted(set(a)))}
    tree = [0] * (len(ranks) + 1)
    result = []

    for i, value in enumerate(a):
        rank = ranks[value]
        count = 0
        j = rank
        while j:
            count += tree[j]
            j -= j & -j

        result.append(min(i, k) - count)

        j = rank
        while j < len(tree):
            tree[j] += 1
            j += j & -j

        if i >= k:
            j = ranks[a[i - k]]
            while j < len(tree):
                tree[j] -= 1
                j += j & -j

    return result
